# loader sweep and disconnect banner
conn_js <- tags$script(HTML("(function(){function AON(ev,fn){if(window.jQuery){window.jQuery(document).on(ev,fn);}else{document.addEventListener(ev,fn);}}function sweep(){document.querySelectorAll('.shiny-spinner-output-container').forEach(function(c){var out=c.querySelector('.shiny-bound-output');if(!out)return;var has=out.children.length>0||out.textContent.trim().length>0;var ld=c.querySelector('.load-container');if(has&&ld)ld.style.display='none';if(!has&&ld)ld.style.display='';});}AON('shiny:value',function(){setTimeout(sweep,80);});AON('shiny:idle',function(){setTimeout(sweep,80);});AON('shiny:error',function(){setTimeout(sweep,80);});setInterval(sweep,2000);function banner(){var b=document.getElementById('conn-lost');if(b)return b;b=document.createElement('div');b.id='conn-lost';b.setAttribute('role','alert');b.setAttribute('aria-live','assertive');b.innerHTML='<span>Connection lost. Displayed results may be stale.</span>';var r=document.createElement('button');r.type='button';r.className='conn-btn';r.textContent='Reload this view';r.addEventListener('click',function(){location.reload();});b.appendChild(r);document.body.appendChild(b);return b;}function lost(){banner();document.body.classList.add('conn-stale');document.querySelectorAll('.tour-wrap').forEach(function(t){if(t.parentNode)t.parentNode.removeChild(t);});['main-content'].forEach(function(id){var m=document.getElementById(id);if(m)m.removeAttribute('aria-hidden');});var nv=document.querySelector('nav.navbar');if(nv)nv.removeAttribute('aria-hidden');}AON('shiny:disconnected',lost);AON('shiny:sessionended',lost);})();"))

# narrow-table scroll cue
